import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水地比","description":"周易折中 - 水地比","frontmatter":{"title":"水地比","description":"周易折中 - 水地比"},"headers":[],"relativePath":"classics/zhezhong/014.md","filePath":"classics/zhezhong/014.md"}'),h={name:"classics/zhezhong/014.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="水地比" tabindex="-1">水地比 <a class="header-anchor" href="#水地比" aria-label="Permalink to “水地比”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>比序卦：眾必有所比，故受之以比。比親輔也，人之類必相親輔然後能安。故既有眾，則必有所比。比所以次師也，為卦上坎下坤。以二體言之，水在地上，物之相切比無閒，莫如水之在地上，故為比也。又眾爻皆陰，獨五以陽剛居君位，眾所親附，而上亦親下，故為比也。</p><p>比：吉。原筮，元永貞，無咎。不寧方來，後夫兇。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>比，親輔也。九五以陽剛居上之中而得其正，上下五陰比而從之。以一人而橅萬邦，以四海而仰一人之象。故筮者得之，則當為人所親輔。然必再筮以自審，有元善長、永正固之德，然後可以當眾之歸而無咎。其未比而有所不安者，亦將皆來歸之。若又遲而後至，則此交已固，彼來已晚，而得兇矣。若欲比人，則亦以是而反觀之耳。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>比吉，道也。人相親比，自為吉道。故雜卦雲：“比樂師憂。”人相親比，必有其道。苟非其道，則有悔咎。故必推原佔決，其可比者而比之。筮謂佔決卜度，非謂以蓍龜也。所比得元永貞，則無咎。元謂有君長之道，永謂可以常久，貞謂得正道。上之比下，必有此三者。下之從上，必求此三者，則無咎也。人之不能自保其安寧，方且來求親比。得所比，則能保其安。當其不寧之時，固宜汲汲以求比。若獨立自恃，求比之志不速，而後則雖夫亦兇矣。夫猶兇，況柔弱者乎？夫，剛立之稱。傳曰：“子南夫也。”又曰：“是謂我非夫。”凡生天地之間者，未有不相親比而能自存者也。雖剛強之至，未有能獨立者也。比之道，由兩志相求。兩志不相求，則睽矣。君懷撫其下，下親輔於上。親戚朋友鄉黨皆然，故當上下合志以相從。苟無相求之意，則離而兇矣。大抵人情相求則合，相持則睽。相持相待，莫先也。人之相親固有道，然而欲比之志不可緩也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>郭氏雍曰：一陽之卦，得位者師、比而已。得君位者為比，得臣位者為師。</p></li><li><p>馮氏椅曰：萃與比下體坤順，同上體水澤不相逺。惟九四一爻有分權之象，故元永貞言於五。比下無分權者，故元永貞言於卦。義各有在也。</p></li><li><p>胡氏一桂曰：六十四卦，惟䝉、比以筮言。䝉貴初，而比貴原者，蓋發䝉之道，當視其初筮之專誠；顯比之道，當致其原筮而謹審。所以不同也。</p></li><li><p>胡氏炳文曰：原筮，本義讀如原蠶、原廟、原田之原，義皆訓再。曰吉，曰無咎，曰兇，皆佔辭。吉，上下相比之佔，統言也。無咎，所比者之佔；兇，比人者之佔，分言也。䝉、比卦辭特發兩筮字，以示佔者之通例。筮得䝉卦辭，䝉求亨者與亨䝉者皆可用；筮得此卦辭，為人所比與求比者皆可用。顧其所處所存者何如耳。䝉之筮問之人者，不一則不專；比之筮問其在我者，不再則不審。不寜方來，指下四陰而言。來者自來，後者自後，吾惟問我之可比不可比，彼之來比不來比，吾不問也。此固王者大公之道，而為九五之顯比者也。</p></li></ul><p>象曰：地上有水，比。先王以建萬國，親諸侯</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>地上有水，水比於地，不容有間。建國親侯，亦先王所以比於天下而無間者也。彖意人來比我，此取我往比人。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>夫物相親比而無間者，莫如水在地上，所以為比也。先王觀比之象，以建萬國，親諸侯。建立萬國，所以比民也；親撫諸侯，所以比天下也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張氏浚曰：水行地上，小大相比，率以歸東。先王法之，建萬國以下比其民，親諸侯以上比其君，若身使臂，臂使指，小大相維，順以聽命，製得其道也。</p></li><li><p>朱子語類雲：伊川言建萬國以比民，民不可盡得而比，故建諸侯使比民，而天子所親者諸侯而已，這便是比天下之道。</p></li><li><p>馮氏當可曰：地上之水，異源同流，畎澮相比以比於川，九川相比以比於海，如萬國諸侯大小相比，而方伯連帥率之以比於天子也。</p></li><li><p>胡氏炳文曰：師之容民畜眾，井田法也，可以使民自相合而無間；比之建國親侯，封建法也，可使君與民相合而無間。</p></li></ul><p>彖曰：比，吉也。</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>此三字疑衍文</p><p>比，輔也；下順從也。</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>此以卦體釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>比吉也。比者，吉之道也。物相親比乃吉道也。比輔也，釋比之義。比者相親附也，下順從也，解卦所以為比也。五以陽居尊位，群下順從以親輔之，之所以為比也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：“比吉也者”，言相親比而得吉也。“比輔也者”，釋比所以得吉。“下順從者”，謂眾陰順從九五也。</p></li><li><p>朱子語類雲：“比吉也”也字羨，當雲“比吉”。“比輔也，下順從也”，比輔也解“比”字，下順從也解“吉”字。</p></li><li><p>楊氏啟新曰：“下順從”以卦體言，實則兼上下。眾陰不曰“上下”而曰“下”者，以九五為主也。至“不寧方來”則曰“上下應”，前是尊上之辭，後是舉眾之辭。</p></li></ul><p>原筮元永貞，無咎。以剛中也，不寧方來，上下應也。後夫兇，其道窮也。</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>亦以卦體釋卦辭。剛中謂五，上下謂五陰。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>推原筮決相比之道，得元永貞而後可以無咎。所謂元永貞，如五是也。以陽剛居中正，盡比道之善者也。以陽剛當尊位為君德元也，居中得正，能永而貞也。卦辭本泛言比道，彖言元永貞者，九五以剛處中正是也。人之生不能保其安寧，方且來求附比。民不能自保，故戴君以求寧。君不能獨立，故保民以為安。不寧而來比者，上下相應也。以聖人之公言之，固至誠求天下之比以安民也；以後王之私言之，不求下民之附則危亡至矣。故上下之志必相應也。在卦言之，上下群陰比於五，五比其眾，乃上下應也。眾必相比而後能遂其生，天地之間，未有不相親比而能遂者也。若相從之志不疾，後則不能成比，雖夫亦兇矣。無所親比，困屈以致兇窮之道也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：凡應字多謂剛柔兩爻相應，此則謂上下。五陰應乎五之剛，又一例也。師、比皆一陽五陰，師之應謂五應二，將之任專也；比之應則謂上下應五，君之分嚴也。</li></ul><p>初六：有孚比之，無咎；有孚盈缶，終來有它吉。</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>有孚比之，無咎；若其充實，則又有它吉也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>初六，比之始也。相比之道，以誠信為本。中心不信而親人，人誰與之？故比之始，必有孚誠，乃無咎也。孚，信之在中也。誠信充實於內，若物之盈滿於缶中也。缶，質素之器。言若缶之盈實其中，外不加文餙，則終能來有它吉也。它，非此也，外也。若誠實充於內，物無不信，豈用餙外以求比乎？誠信中實，雖它外皆當感而來從。孚信，比之本也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏汝諧曰：五為比之主，初最遠而非其應，何以有吉義？蓋幾生於應物之先，而誠出於志之未變，故以信求比，何咎之有？盈，充也。缶，素器也。居下而位卑，擴吾之信以充之，雖逺而非其應，終必應而有它吉矣。有它吉者，非期於必得而得之也。</p></li><li><p>胡氏炳文曰：與人交，止於信。親比之初，能有誠信，所以比之無咎。及其誠信充實，則非特無咎，又有它吉。初六不與五應，故曰有它。大過九四、中孚初九皆曰有它，彼則戒其有它向之心，此則許其有它至之吉也。</p></li></ul><p>象曰：比之初六，有孚比之，無咎。有孚盈缶，終來有它吉</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>言比之初六者，比之道在乎始也。始能有孚，則終致有它之吉。其始不誠，終焉得吉？上六之兇，由無首也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>蔣氏悌生曰：爻辭有孚，凡兩更端及盈缶等語，象傳皆略之，直舉初六為言，可見比之要道在乎始。先此義與卦辭“後夫兇”之意相發明。</li></ul><p>六二：比之自內，貞吉。</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>柔順中正，上應九五，自內比外而得其正，吉之道也。佔者如是，則正而吉矣。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二與五為正應，皆得中正，以中正之道相比者也。二處於內，自內謂由已也。擇才而用，雖在乎上，而以身許國，必由於己。已以得君，道合而進，乃得正而吉也。以中正之道應上之求，乃自內也，不自失也。汲汲以求比者，非君子自重之道，乃自失也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>梁氏寅曰：二與五為比，由內而比外者也。凡貞吉，有爻之本善者，有爻非貞而為之戒者。此曰貞吉，爻之本善也。言自內比外而得其正，是以吉也。</p></li><li><p>谷氏家傑曰：自內之所有者，以比之逹不變塞也。即此是正，故吉。</p></li></ul><p>象曰：比之自內，貞吉</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>得正則不自失矣。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>守己中正之道以待上之求，乃不自失也。易之為戒嚴密，二雖中正質柔體順，故有貞吉自失之戒。戒之自守以待上之求，無乃渉後兇乎？曰：士之脩己乃求上之道，降志辱身非自重之道也，故伊尹、武侯救天下之心非不切，必待禮至然後出也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱氏震曰：六二柔也，恐其自失也。二處乎內，待上之求然後應之，比之自內者也，故曰不自失也。</li></ul><p>六三：比之匪人。</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>陰柔不中正，承乘應皆陰，所比皆非其人之象，其佔大兇，不言可知。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>三不中正，而所比皆不中正。四陰柔而不中，二存應而比初，皆不中正，匪人也。比於匪人，其失可知，悔吝不假言也，故可傷。二之中正而謂之匪人，隨時取義，各不同也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：四自外比二，為五應近不相得，遠則無應，所與比者皆非已親，故曰“比之匪人”。</p></li><li><p>朱子語類雲：初應四為比得其人，二應五亦為比得其人，惟三乃應上，上為比之無首者，故為“比之匪人”也。</p></li><li><p>趙氏彥肅曰：初比於五，先也；二應也；四承也；六三無是三者之義，將不能比五矣。</p></li></ul><p>象曰：比之匪人，不亦傷乎</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>人之相比，求安吉也。乃比於匪人，必將反得悔吝，其亦可傷矣。深戒失所比也。</p><p>六四：外比之，貞吉。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以柔居柔，外比九五，為得其正，吉之道也。佔者如是，則正而吉矣。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四與初不相應，而五比之外，比於五乃得貞正而吉也。君臣相比，正也。相比相與，宜也。五剛陽中正，賢也，居尊位在上也。親賢從上，比之正也，故為貞吉。以六居四，亦為得正之義。又陰柔不中之人，能比於剛明中正之賢，乃得正而吉也。又比賢從上，必以正道，則吉也。數說相須，其義始備。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>易氏祓曰：易以上卦為外，下卦為內。而二體亦各有內外，四與五同體而言外比者，亦所以比五也。</p></li><li><p>李氏過曰：二與四皆比於五，二應五在卦之內，故言“比之自內”；四承五在卦之外，故言“外比”。之外內雖異，而得其所比，其義一也，故皆言貞吉。</p></li></ul><p>象曰：外比於賢，以從上也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>外比謂從五也。五剛明中正之賢，又居君位，四比之，是比賢且從上，所以吉也。</p><p>九五：顯比，王用三驅，失前禽，邑人不誡，吉。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>一陽居尊，剛健中正，卦之群陰皆來比已，顯其比而無私，如天子不合圍，開一面之網，來者不拒，去者不追，故為用三驅失前禽而邑人不誡之象。蓋雖私屬亦喻上意，不相警備以求必得也。凡此皆吉之道，佔者如是則吉也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>五居君位，處中得正，盡比道之善者也。人君比天下之道，當顯明其比道而已。如誠意以待物，恕己以及人，發政施仁，使天下蒙其惠澤，是人君親比天下之道也。如是，天下孰不親比於上？若乃暴其小仁，違道幹譽，欲以求下之比，其道亦狹矣，其能得天下之比乎？故聖人以九五盡比道之正，取三驅為喻曰：王用三驅，失前禽，邑人不誡吉。先王以四時之畋不可廢也，故推其仁心為三驅之禮，乃禮所謂天子不合圍也。成湯祝網是其義也。天子之畋，圍合其三面，前開一路，使之可去，不忍盡物，好生之仁也。只取其不用命者，不出而反入者也。禽獸前去者皆免矣，故曰失前禽也。王者顯明其比道，天下自然來比，來者撫之，固不煦煦然求比於物，若田之三驅，禽之去者從而不追，來者則取之也。此王道之大，所以其民皡皡而莫知為之者也。邑人不誡，吉言其至公不私，無遠邇親踈之別也。邑者，居邑，易中所言邑皆同。王者所都，諸侯國中也。誡，期約也。待物之一，不期誡於居邑，如是則吉也。聖人以大公無私治天下，於顯比見之矣。非惟人君比天下之道如此，大率人之相比莫不然。以臣於君言之，竭其忠誠，致其才力，乃顯其比君之道也。用之與否在君而已，不可阿諛逢迎求其比已也。在朋友亦然，修身誠意以待之，親已與否在人而已，不可巧言令色曲從苟合以求人之比己也。於鄉黨親戚於眾人莫不皆然，三驅失前禽之義也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類 問：伊川解“顯比，王用三驅，失前禽”所謂“來者撫之，去者不追”與“失前禽而殺不去者”所譬頗不相類，如何？ 曰：田獵之禮，置旃以為門，刈草以為長圍。田獵者自門驅而入，禽獸向我而出者皆免，惟被驅而入者皆獲。故以前禽比去者不追，獲者比來則取之。大意如此，無緣得一一相似。伊川解此句不須疑，但“邑人不誡吉”一句似可疑，恐易之文義不如此耳。 又云：邑人不誡，如有聞無聲，言其自不消相告誡。又如歸市者不止，耕者不變相似。</p></li><li><p>問：伊川解“顯比，王用三驅，失前禽”所謂“來者撫之，去者不追”與“失前禽而殺不去者”所譬頗不相類，如何？ 曰：田獵之禮，置旃以為門，刈草以為長圍。田獵者自門驅而入，禽獸向我而出者皆免，惟被驅而入者皆獲。故以前禽比去者不追，獲者比來則取之。大意如此，無緣得一一相似。伊川解此句不須疑，但“邑人不誡吉”一句似可疑，恐易之文義不如此耳。</p></li><li><p>又云：邑人不誡，如有聞無聲，言其自不消相告誡。又如歸市者不止，耕者不變相似。</p></li><li><p>胡氏炳文曰 ：諸陰爻皆言比，陰比陽也。五言顯比，陽為陰所比也。師比之五皆取田象，師之田有禽，害物之禽也；比之失前禽，背已之禽也。在師則執之，王者之義也；在比能失之，王者之仁也。</p></li><li><p>梁氏寅曰 ：九五陽剛中正，為比之主。陽剛則明而不暗，中正則公而不私，此其所以為顯比也。以象言之，如田狩而用三驅，失前禽，來者不拒，去者不追，此上之比下也，固顯比也；比下既得其道，則雖私屬亦喻上意而不待告誡，此下之比上也，亦顯比也。上下之相比，同一顯明之道，又安有不吉乎？</p></li><li><p>林氏希元曰 ：顯與隱對，光明正大而無隱伏回曲闇昧褊窄者顯也，隱伏回曲闇昧褊窄而不光明正大者隱也。王者以父母天下為職，生養教誨，但知吾分所當為，盡其道而為之，至於民之感恩與否則聽其在彼，初不屑屑焉。暴其私恩小惠，違道幹譽，以求百姓之我親，此其施為舉措何等光明正大，而豈有隱伏回曲闇昧褊窄之病？故謂之顯比。譬如王者解一面之網，用三驅之田，禽獸向我而入者取之，揹我而前去者則失之，初不求於必得。至於私屬亦喻上意，不相警備以求必得焉。夫王用三驅，失前禽者，王道之得；邑人不誡者，王化之行。凡此皆吉之道也。王者能如九五之顯比，則亦王道得而王化行矣。</p></li><li><p>陸氏振奇曰 ：三驅失禽，置失得於勿恤者，狀蕩平之王心；邑人不誡，泯知識於大順者，狀熙皥之王化。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>本義解“邑人不誡”謂不相警備以求必得，似以為求所失之前禽也。然語類只作“冇聞無聲”之意，尤為精切。蓋言王者田獵而近郊之處略不驚擾耳。本義系朱子未脩改之書，故其後來講論每有不同者皆此類也。大抵爻意是以田獵喻王者皥皥之氣象，前禽失而不追，邑人居而不誡。遠去者若不知有王者之親，乃所以為親之至也；近附者若不知有王者之尊，乃所以為尊之至也。顯比之世，凡有血氣莫不尊親，而所謂大順大化不見其跡者又如此。</p><p>象曰：顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>由上之德使不偏也。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>顯比所以吉者，以其所居之位得正中也。處正中之地，乃由正中之道。比以不偏為善，故云正中。凡言正中者，其處正得中也。比與隨是也。言中正者，得中與正也，訟與需是也。禮取不用命者，乃是舍順取逆也。順命而去者皆免矣。比以向背而言，謂去者為逆，來者為順也。故所失者前去之禽也。言來者撫之，去者不追也。不期誡於親近，上之使下中平不偏，遠近如一也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>丘氏富國曰：舍逆謂舍上一陰，陰以乘陽為逆也；取順謂取下四陰，陰以承陽為順也。失上一陰，故曰失前禽。</p></li><li><p>胡氏炳文曰：師之使不當，誰使之？五也。比之使中，誰使之？亦五也。</p></li></ul><p>上六：比之無首，兇。</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>陰柔居上，無以比下，兇之道也，故為無首之象，而其佔則兇也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>六居上，比之終也。首，謂始也。凡比之道，其始善，則其終善矣。有其始而無其終者或有矣，未有無其始而有終者也。故比之無首，至終則兇也。此據比終而言，然上六陰柔不中，處險之極，固非克終者也。始比不以道，隙於終者，天下多矣。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：無首，後也。處卦之終，是後夫也。為時所棄，宜其兇也。</p></li><li><p>王氏申子曰：五以一陽居尊，四陰比之於下，故彖傳曰“下順從也”。而上六孤立於外而不從，豈非後夫之象？</p></li></ul><p>象曰：比之無首，無所終也</p><h3 id="本義-13" tabindex="-1">本義 <a class="header-anchor" href="#本義-13" aria-label="Permalink to “本義”">​</a></h3><p>以上下之象言之，則為無首；以終始之象言之，則為無終。無首則無終矣。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>比既無首，何所終乎？相比有首，猶或終違。始不以道終，復何保？故曰無所終也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏簡曰：由初而比之，其比也誠。比不於其初及終而始求比，不忠不信，人所不與，兇之道也。首，初也。有始則有終，無始何以能終？故曰無所終也。</p></li><li><p>蔣氏悌生曰：即卦辭“後夫兇”之義。</p></li></ul>',110)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
